/* Œconomia — Entraînement : thème « Croissance et PIB » (24 exercices, trois niveaux). */
(function () {
  const X = OEC.exo, { rnd, pick, fmt } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");

  X.theme({ id: "croissance", nom: "Croissance et PIB",
    intro: "Comment mesure-t-on la richesse produite par un pays, et d’où vient sa croissance ? Ces exercices vous entraînent à calculer et à interpréter le PIB, à distinguer valeurs nominales et réelles, à raisonner sur la croissance de long terme et à discuter de ses limites.",
    notions: ["pib", "modele-solow", "division-travail", "destruction-creatrice", "cycles", "institutions-inclusives", "stagnation-seculaire", "capabilites"] });

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "cr1-ce-qui-compte", theme: "croissance", niveau: 1, type: "qcm", notion: "pib",
    titre: "Qu’est-ce qui compte dans le PIB ?", competence: "Savoir ce que mesure le produit intérieur brut.",
    enonce: P("Laquelle de ces opérations, réalisées en Suisse cette année, est comptée dans le PIB suisse de l’année ?"),
    options: ["L’achat d’une voiture d’occasion fabriquée il y a cinq ans.", "Un repas préparé à la maison pour sa famille.", "Une coupe de cheveux payée chez un coiffeur.", "L’achat d’actions d’une entreprise suisse en Bourse."], c: 2, pourquoi: ["La voiture a été comptée dans le PIB l’année de sa fabrication ; la revendre ne crée aucune production nouvelle.", "Le repas est produit, mais il n’est ni vendu ni payé : le PIB ne compte pas le travail domestique.", null, "Acheter des actions est un échange de titres, une opération financière : aucune production nouvelle n’est créée."],
    explication: P("Le PIB mesure la valeur des biens et services <b>produits</b> pendant l’année sur le territoire et <b>échangés sur un marché</b> (ou fournis par les administrations). La coupe de cheveux est un service produit et vendu cette année.", "La voiture d’occasion a été comptée l’année de sa fabrication ; le repas à la maison n’est pas vendu, il n’est pas compté ; l’achat d’actions est un simple transfert de propriété, pas une production.") },

  { id: "cr1-taux", theme: "croissance", niveau: 1, type: "calcul", notion: "pib",
    titre: "Du taux de croissance au nouveau PIB", competence: "Calculer le PIB de l’année à partir de celui de l’année précédente et du taux de croissance.",
    gen: () => ({ y0: rnd(700, 860), g: pick([-2.5, -1.2, 0.4, 0.8, 1.2, 1.6, 2.1, 2.9, 3.5, 5.0]) }),
    enonce: (p) => P(`Le PIB réel d’un pays était de <b>${p.y0} milliards</b> de francs l’an dernier. Cette année, sa croissance est de <b>${fmt(p.g, 1)} %</b>.`, "Quel est le PIB réel de cette année ? Arrondissez à un dixième de milliard."),
    champs: [{ label: "PIB réel de cette année", unite: "milliards de fr.", tol: 0.06 }],
    reponses: (p) => [X.arr(p.y0 * (1 + p.g / 100), 1)],
    indice: "Le nouveau PIB est l’ancien PIB multiplié par (1 + taux de croissance ÷ 100).",
    correction: (p) => { const v = p.y0 * (1 + p.g / 100); return P(`PIB = ${p.y0} × (1 ${p.g < 0 ? "−" : "+"} ${fmt(Math.abs(p.g), 1)} ÷ 100) = ${p.y0} × ${fmt(1 + p.g / 100, 3)}`, `≈ <b>${fmt(X.arr(v, 1), 1)} milliards</b> de francs.`, p.g < 0 ? "La production a reculé : si cette baisse dure au moins deux trimestres consécutifs, on parle de récession." : "La production a augmenté. En Suisse, la croissance annuelle tourne souvent autour de 1 à 2 %."); } },

  { id: "cr1-par-habitant", theme: "croissance", niveau: 1, type: "calcul", notion: "pib",
    titre: "Le PIB par habitant", competence: "Calculer un PIB par habitant.",
    gen: () => ({ y: rnd(780, 880), pop: rnd(86, 93) / 10 }),
    enonce: (p) => P(`Le PIB d’un pays est de <b>${p.y} milliards</b> de francs pour une population de <b>${fmt(p.pop, 1)} millions</b> d’habitants (des chiffres proches de ceux de la Suisse).`, "Quel est le PIB par habitant ? Arrondissez à la centaine de francs."),
    champs: [{ label: "PIB par habitant", unite: "fr.", tol: 60 }],
    reponses: (p) => [Math.round(p.y * 100 / Math.round(p.pop * 10)) * 100],
    indice: "Divisez le PIB par la population, en faisant attention aux unités : milliards ÷ millions = milliers.",
    correction: (p) => P(`PIB par habitant = ${p.y} milliards ÷ ${fmt(p.pop, 1)} millions`, `= ${fmt(p.y / p.pop, 3)} milliers de francs, soit environ <b>${fmt(Math.round(p.y * 100 / Math.round(p.pop * 10)) * 100)} francs</b> par habitant et par an.`, "C’est une <b>moyenne</b> : elle ne dit rien de la répartition des revenus entre les habitants.") },

  { id: "cr1-vf-limites", theme: "croissance", niveau: 1, type: "vf", notion: "pib",
    titre: "Les limites du PIB", competence: "Savoir ce que le PIB ne mesure pas.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Le travail bénévole dans une association est compté dans le PIB.", false, "Il n’est pas rémunéré ni vendu : il n’entre pas dans le PIB, alors qu’il a une grande valeur sociale. En Suisse, l’OFS l’estime à part, dans un « compte satellite »."],
      ["Les dépenses pour réparer les dégâts d’une inondation font augmenter le PIB.", true, "Les travaux de réparation sont une production vendue. Le PIB ne retire pas les destructions : c’est l’une de ses limites comme mesure du bien-être."],
      ["Un PIB par habitant élevé garantit que chaque habitant a un revenu élevé.", false, "C’est une moyenne : un pays très inégal peut avoir un PIB par habitant élevé et beaucoup de pauvres."],
      ["Le PIB ne mesure pas l’épuisement des ressources naturelles ni la pollution.", true, "C’est pourquoi on le complète par des indicateurs environnementaux et de bien-être, comme le recommandait le rapport Stiglitz-Sen-Fitoussi (2009)."]
    ] },

  { id: "cr1-nominal-reel", theme: "croissance", niveau: 1, type: "qcm", notion: "pib",
    titre: "PIB nominal et PIB réel", competence: "Distinguer une hausse des prix d’une hausse de la production.",
    enonce: P("Cette année, le PIB nominal d’un pays a augmenté de 3 %, et les prix ont augmenté en moyenne de 2 %. Que peut-on dire de la production ?"),
    options: ["Elle a augmenté de 3 %.", "Elle a augmenté d’environ 1 %.", "Elle a augmenté de 5 %.", "Elle a baissé de 1 %."], c: 1, pourquoi: ["3 % est la hausse du PIB nominal, qui mélange production et prix : il faut retirer la hausse des prix de 2 %.", null, "Il faut soustraire la hausse des prix, pas l’ajouter : le PIB nominal est gonflé par l’inflation.", "La valeur de la production a augmenté plus vite que les prix (3 % contre 2 %) : la production réelle a donc augmenté."],
    explication: P("Le PIB <b>nominal</b> est mesuré aux prix de l’année : il augmente si l’on produit plus, mais aussi si les prix montent. Le PIB <b>réel</b> retire l’effet des prix. Ici, la croissance réelle est d’environ 3 − 2 = <b>1 %</b> (plus précisément 1,03 ÷ 1,02 − 1 ≈ 0,98 %).", "Quand on parle de « croissance économique », on parle toujours de la croissance du PIB réel.") },

  { id: "cr1-valeur-ajoutee", theme: "croissance", niveau: 1, type: "calcul", notion: "pib",
    titre: "Le PIB comme somme des valeurs ajoutées", competence: "Éviter de compter deux fois les consommations intermédiaires.",
    gen: () => { const ble = rnd(20, 40), farine = ble + rnd(15, 30), pain = farine + rnd(40, 80); return { ble, farine, pain }; },
    enonce: (p) => P(`Un agriculteur vend du blé au meunier pour <b>${p.ble} francs</b>. Le meunier en fait de la farine qu’il vend au boulanger pour <b>${p.farine} francs</b>. Le boulanger vend le pain aux clients pour <b>${p.pain} francs</b>. (On suppose que l’agriculteur n’a rien acheté.)`, "Calculez la valeur ajoutée du meunier et celle du boulanger. Calculez aussi le montant compté en trop si l’on additionnait les ventes des trois au lieu de leurs valeurs ajoutées."),
    champs: [{ label: "Valeur ajoutée du meunier", unite: "fr.", tol: 0.5 }, { label: "Valeur ajoutée du boulanger", unite: "fr.", tol: 0.5 }, { label: "Montant compté en trop", unite: "fr.", tol: 0.5 }],
    reponses: (p) => [p.farine - p.ble, p.pain - p.farine, p.ble + p.farine],
    indice: "La valeur ajoutée d’une entreprise est la différence entre ce qu’elle vend et ce qu’elle achète aux autres. Le montant compté en trop est la somme des ventes moins la valeur du produit final.",
    correction: (p) => P(`Valeur ajoutée du meunier : ${p.farine} − ${p.ble} = <b>${p.farine - p.ble} francs</b>. Valeur ajoutée du boulanger : ${p.pain} − ${p.farine} = <b>${p.pain - p.farine} francs</b>. Celle de l’agriculteur est de ${p.ble} francs.`, `Contribution de la filière au PIB : ${p.ble} + ${p.farine - p.ble} + ${p.pain - p.farine} = ${p.pain} francs, la valeur du produit final.`, `Additionner toutes les ventes donnerait ${p.ble + p.farine + p.pain} francs. Le montant compté en trop est ${p.ble + p.farine + p.pain} − ${p.pain} = <b>${p.ble + p.farine} francs</b>, soit le blé et la farine comptés plusieurs fois. C’est pourquoi le PIB est la somme des <b>valeurs ajoutées</b>.`) },

  { id: "cr1-crosse", theme: "croissance", niveau: 1, type: "qcm", notion: "division-travail",
    titre: "Quand la croissance a-t-elle commencé ?", competence: "Situer le décollage de la croissance dans l’histoire.",
    enonce: P("Selon les estimations de l’historien Angus Maddison, comment a évolué le revenu moyen par habitant dans le monde au cours des deux derniers millénaires ?"),
    options: ["Il a augmenté régulièrement d’environ 1 % par an depuis l’Antiquité.", "Il a très peu progressé jusque vers 1800, puis a été multiplié par plus de dix en deux siècles.", "Il a baissé depuis la révolution industrielle.", "Il a surtout augmenté au Moyen Âge, grâce à l’agriculture."], c: 1, pourquoi: ["Une croissance de 1 % par an pendant deux mille ans aurait multiplié le revenu par plusieurs centaines de millions : ce n’est pas ce qu’on observe.", null, "C’est l’inverse : la révolution industrielle marque le début de la hausse rapide du revenu par habitant.", "Au Moyen Âge, les progrès agricoles ont surtout permis à la population de croître ; le revenu par habitant a très peu changé (le « piège malthusien »)."],
    explication: P("Pendant des siècles, les gains de productivité se traduisaient surtout par une hausse de la population : c’est le « piège malthusien ». Avec la révolution industrielle, à partir de la fin du XVIIIe siècle en Angleterre, le revenu par habitant décolle : il a été multiplié par plus de dix depuis 1820. La courbe a la forme d’une « crosse de hockey ».") },

  { id: "cr1-suisse-pib", theme: "croissance", niveau: 1, type: "document", notion: "cycles",
    titre: "La croissance suisse récente", competence: "Lire une série de taux de croissance.",
    enonce: P("Croissance du PIB réel de la Suisse, en % par rapport à l’année précédente.") +
      `<table><thead><tr><th>2019</th><th>2020</th><th>2021</th><th>2022</th><th>2023</th><th>2024</th><th>2025</th></tr></thead><tbody><tr><td>1,1</td><td>−2,3</td><td>6,2</td><td>3,5</td><td>1,0</td><td>1,5</td><td>1,6</td></tr></tbody></table><p class="ex-source">Source : SECO, PIB de la Suisse selon l’approche par la dépense, données brutes, état du 3 septembre 2026 (avec les données annuelles révisées de l’OFS du 25 août 2026). Valeurs arrondies, non corrigées des événements sportifs. Les comptes nationaux sont révisés chaque année.</p>` +
      P("Quelle affirmation est correcte ?"),
    options: ["Le PIB suisse a été plus faible en 2021 qu’en 2019.", "Le PIB a reculé en 2020, avec la pandémie, puis fortement rebondi en 2021.", "La Suisse a connu une récession en 2023, puisque la croissance n’était que de 1,0 %.", "Les chiffres montrent que la Suisse ne connaît jamais de baisse du PIB."], c: 1, pourquoi: ["Après −2,3 % en 2020 et +6,2 % en 2021, le PIB de 2021 dépasse celui de 2019 d’environ 4 %.", null, "Une croissance de 1,0 % reste positive, la production a donc augmenté. Une récession suppose une baisse de la production.", "Le tableau montre justement une baisse en 2020 (−2,3 %)."],
    explication: P("En 2020, la croissance est négative : la production a baissé, à cause des mesures sanitaires. En 2021, elle rebondit fortement, et le PIB dépasse alors son niveau de 2019 (−2,3 % puis +6,2 % donnent environ +3,8 %).", "En 2023, la croissance est faible mais positive : la production a augmenté, il ne s’agit pas d’une récession. Elle se raffermit ensuite, à 1,5 % en 2024 et 1,6 % en 2025.") },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "cr2-regle-70", theme: "croissance", niveau: 2, type: "calcul", notion: "pib",
    titre: "La règle de 70", competence: "Estimer le temps de doublement d’une grandeur.",
    gen: () => ({ g: pick([2.5, 3, 4, 5, 7]), n: pick([0.5, 1, 1.5]) }),
    enonce: (p) => P(`Le PIB réel d’un pays croît de <b>${fmt(p.g, 1)} %</b> par an, et sa population de <b>${fmt(p.n, 1)} %</b> par an.`, "Selon la règle de 70, en combien d’années environ le PIB total va-t-il doubler ? Et le PIB par habitant ? Arrondissez à une décimale."),
    champs: [{ label: "Doublement du PIB total", unite: "ans", tol: 0.5 }, { label: "Doublement du PIB par habitant", unite: "ans", tol: 0.5 }],
    reponses: (p) => [X.arr(70 / p.g, 1), X.arr(70 / (p.g - p.n), 1)],
    indice: "La règle relie le nombre 70, le taux de croissance en % et le nombre d’années. Pour le PIB par habitant, commencez par calculer son taux de croissance. Vérifiez avec un cas connu : à 7 % par an, une grandeur double en dix ans.",
    correction: (p) => P(`PIB total : 70 ÷ ${fmt(p.g, 1)} ≈ <b>${fmt(70 / p.g, 1)} ans</b>.`, `Croissance du PIB par habitant ≈ ${fmt(p.g, 1)} − ${fmt(p.n, 1)} = ${fmt(p.g - p.n, 1)} % par an. PIB par habitant : 70 ÷ ${fmt(p.g - p.n, 1)} ≈ <b>${fmt(70 / (p.g - p.n), 1)} ans</b>.`, `La croissance de la population retarde le doublement du niveau de vie moyen de ${fmt(70 / (p.g - p.n) - 70 / p.g, 1)} ans. De petites différences de croissance font de grandes différences à long terme : à 1 % par an, il faut 70 ans pour doubler ; à 7 %, comme la Chine pendant des décennies, 10 ans seulement.`) },

  { id: "cr2-composee", theme: "croissance", niveau: 2, type: "calcul", notion: "pib",
    titre: "La croissance composée", competence: "Calculer l’effet cumulé d’une croissance annuelle.",
    gen: () => ({ g: pick([3, 4, 5, 6]), i: pick([1, 2, 3]), n: pick([10, 20, 25]) }),
    enonce: (p) => P(`Le PIB nominal par habitant d’un pays croît de <b>${fmt(p.g)} %</b> par an pendant <b>${p.n} ans</b>, alors que les prix augmentent de <b>${fmt(p.i)} %</b> par an.`, "Par combien le PIB nominal par habitant est-il multiplié au total ? Et le PIB réel par habitant ? Arrondissez à deux décimales."),
    champs: [{ label: "PIB nominal multiplié par", unite: "", tol: 0.011 }, { label: "PIB réel multiplié par", unite: "", tol: 0.02 }],
    reponses: (p) => [X.arr(Math.pow(1 + p.g / 100, p.n), 2), X.arr(Math.pow((1 + p.g / 100) / (1 + p.i / 100), p.n), 2)],
    indice: "Coefficient multiplicateur = (1 + taux) puissance nombre d’années. Le PIB réel s’obtient en divisant le coefficient nominal par celui des prix.",
    correction: (p) => { const k = Math.pow(1 + p.g / 100, p.n), q = Math.pow(1 + p.i / 100, p.n); return P(`Nominal : ${fmt(1 + p.g / 100, 3)}<sup>${p.n}</sup> ≈ <b>${fmt(k, 2)}</b> (${fmt(k, 4)} avant arrondi).`, `Prix : ${fmt(1 + p.i / 100, 3)}<sup>${p.n}</sup> ≈ ${fmt(q, 2)} (${fmt(q, 4)} avant arrondi). Réel : ${fmt(k, 4)} ÷ ${fmt(q, 4)} ≈ <b>${fmt(k / q, 2)}</b>, soit une hausse réelle d’environ ${fmt((k / q - 1) * 100, 0)} %.`, `Attention : ce n’est pas ${p.n} × ${fmt(p.g)} = ${fmt(p.n * p.g)} %, car chaque année la croissance s’applique à un niveau déjà plus élevé. Et la hausse nominale (${fmt((k - 1) * 100, 0)} %) surestime l’amélioration du pouvoir d’achat.`); } },

  { id: "cr2-solow", theme: "croissance", niveau: 2, type: "qcm", notion: "modele-solow",
    titre: "Le modèle de Solow", competence: "Comprendre les rendements décroissants du capital.",
    enonce: P("Selon le modèle de croissance de Robert Solow (1956), que se passe-t-il si un pays se contente d’accumuler toujours plus de machines, sans progrès technique ?"),
    options: ["Sa croissance s’accélère, car chaque machine supplémentaire rend les précédentes plus productives.", "Chaque machine rapporte un peu moins que la précédente, et la croissance par habitant finit par s’arrêter.", "Sa production baisse, car les machines remplacent peu à peu les travailleurs et réduisent l’emploi.", "Sa croissance devient négative, car l’accumulation de capital provoque de l’inflation."], c: 1, pourquoi: ["Les rendements du capital sont décroissants : chaque machine rapporte moins que la précédente, la croissance ralentit au lieu d’accélérer.", null, "Plus de machines par travailleur augmente la production, mais de moins en moins : elle ne baisse pas.", "Le modèle de Solow ne parle pas d’inflation : la croissance par habitant tend vers zéro, sans devenir négative."],
    explication: P("Le capital a des <b>rendements décroissants</b> : une première machine fait beaucoup gagner, la vingtième beaucoup moins. À force d’accumuler, l’investissement ne fait plus que remplacer les machines usées. À long terme, seule la hausse de l’efficacité, le <b>progrès technique</b>, permet au revenu par habitant de continuer à croître.", "C’est ce qui a poussé Lucas, Romer, Aghion et Howitt à chercher d’où vient ce progrès : éducation, recherche, innovation.") },

  { id: "cr2-comptabilite", theme: "croissance", niveau: 2, type: "calcul", notion: "modele-solow",
    titre: "La comptabilité de la croissance", competence: "Calculer la contribution du progrès technique (résidu de Solow).",
    gen: () => ({ y: pick([2, 2.5, 3, 3.5, 4]), k: pick([2, 3, 4]), l: pick([0, 0.5, 1]) }),
    enonce: (p) => P("La croissance de la production peut se décomposer ainsi : <b>croissance du PIB = 0,3 × croissance du capital + 0,7 × croissance du travail + progrès technique</b> (productivité globale des facteurs).", "Cette formule suppose des rendements d’échelle constants et des facteurs payés à leur productivité marginale. Les coefficients 0,3 et 0,7 sont alors les parts du capital et du travail dans le revenu.", `Dans un pays, le PIB croît de <b>${fmt(p.y)} %</b>, le capital de <b>${fmt(p.k)} %</b> et le travail (heures travaillées) de <b>${fmt(p.l)} %</b>.`, "Quelle est la contribution du progrès technique ? Arrondissez à deux décimales."),
    champs: [{ label: "Progrès technique", unite: "points de %", tol: 0.011 }],
    reponses: (p) => [Math.round((p.y - 0.3 * p.k - 0.7 * p.l) * 100) / 100],
    indice: "Progrès technique = croissance du PIB − 0,3 × croissance du capital − 0,7 × croissance du travail.",
    correction: (p) => { const r = p.y - 0.3 * p.k - 0.7 * p.l; return P(`Contribution du capital : 0,3 × ${fmt(p.k)} = ${fmt(0.3 * p.k, 2)} point ; du travail : 0,7 × ${fmt(p.l)} = ${fmt(0.7 * p.l, 2)} point.`, `Progrès technique = ${fmt(p.y)} − ${fmt(0.3 * p.k, 2)} − ${fmt(0.7 * p.l, 2)} = <b>${fmt(r, 2)} point de %</b>, soit environ ${fmt(100 * r / p.y, 0)} % de la croissance.`, "C’est le « résidu de Solow », que Moses Abramovitz appelait « la mesure de notre ignorance » : la part de la croissance qu’on n’explique pas par plus de capital et plus de travail."); } },

  { id: "cr2-vf-innovation", theme: "croissance", niveau: 2, type: "vf", notion: "destruction-creatrice",
    titre: "Innovation et destruction créatrice", competence: "Comprendre le rôle de l’innovation selon Schumpeter.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["La destruction créatrice signifie que l’innovation profite d’abord aux entreprises déjà installées.", false, "Elle menace au contraire les entreprises installées, que de nouvelles venues remplacent. Des entreprises et des emplois disparaissent, d’autres apparaissent. Il y a des perdants, au moins temporairement."],
      ["Selon Aghion et Howitt, une concurrence plus forte décourage l’innovation des entreprises proches de la frontière technologique.", false, "La relation est plus nuancée : la concurrence pousse les entreprises proches de la frontière technologique à innover pour garder leur avance, mais peut décourager celles qui sont très en retard."],
      ["Pour Schumpeter, l’entrepreneur innovateur est le moteur du capitalisme.", true, "Il introduit de nouveaux produits, procédés ou organisations, et bouleverse les marchés existants."],
      ["Une idée, comme une recette ou un logiciel, peut être utilisée par beaucoup de personnes à la fois sans s’user.", true, "C’est ce que Paul Romer appelle la « non-rivalité » des idées, qui explique qu’elles puissent nourrir une croissance durable."]
    ] },

  { id: "cr2-recession", theme: "croissance", niveau: 2, type: "qcm", notion: "cycles",
    titre: "Reconnaître une récession", competence: "Utiliser la définition courante d’une récession.",
    enonce: P("Voici la croissance du PIB réel d’un pays, trimestre par trimestre (par rapport au trimestre précédent) : +0,4 %, +0,1 %, −0,2 %, −0,3 %, +0,2 %. Que peut-on dire ?"),
    options: ["Il n’y a pas eu de récession, car la croissance sur l’année est positive.", "Le pays est entré en récession au sens courant, avec deux trimestres consécutifs de baisse du PIB.", "Le pays est en dépression.", "Il y a eu une récession dès le deuxième trimestre, car la croissance a ralenti."], c: 1, pourquoi: ["La définition courante porte sur des trimestres consécutifs, pas sur l’année entière : deux trimestres de baisse suffisent.", null, "Une dépression est une récession beaucoup plus longue et profonde, comme dans les années 1930 ; ici, la baisse est faible et courte.", "Au deuxième trimestre, la croissance ralentit mais reste positive : le PIB augmente encore."],
    explication: P("Selon la définition la plus courante, une <b>récession</b> correspond à au moins <b>deux trimestres consécutifs de baisse du PIB réel</b>, ce qui est le cas aux troisième et quatrième trimestres. Un simple ralentissement, comme au deuxième trimestre, n’est pas une récession.", "Une <b>dépression</b> désigne une récession beaucoup plus longue et profonde, comme celle des années 1930. Certains organismes, comme le NBER aux États-Unis, utilisent une définition plus large, fondée aussi sur l’emploi et les revenus.") },

  { id: "cr2-suisse-riche", theme: "croissance", niveau: 2, type: "redaction", notion: "institutions-inclusives",
    titre: "Pourquoi la Suisse est-elle si riche ?", competence: "Mobiliser plusieurs facteurs de croissance pour expliquer un cas.",
    enonce: P("Au début du XIXe siècle, la Suisse n’avait ni charbon ni accès à la mer. Ses régions de montagne étaient pauvres et beaucoup d’habitants émigraient, même si le textile et l’horlogerie y étaient déjà bien implantés. Elle compte aujourd’hui parmi les pays au revenu par habitant le plus élevé du monde.", "<b>Consigne :</b> expliquez cette réussite en mobilisant au moins trois facteurs de croissance. Pour chacun, donnez un exemple suisse et montrez son effet sur la productivité, puis concluez en une phrase. Longueur attendue, 10 à 15 lignes."),
    criteres: ["La réponse mobilise au moins trois facteurs distincts parmi le capital humain (apprentissage, écoles polytechniques), l’innovation et la spécialisation (horlogerie, machines, pharmacie, finance), les institutions (stabilité, État de droit, fédéralisme, démocratie directe) et l’ouverture (commerce, travailleurs et capitaux étrangers). Elle peut citer des facteurs plus discutés, comme l’absence de destructions de guerre, la place financière, l’afflux de capitaux ou la fiscalité.", "Chaque facteur est illustré par un exemple suisse précis.", "Elle relie chaque facteur à la productivité.", "Elle se termine par une phrase de conclusion, par exemple sur l’absence de ressources naturelles ou sur le rôle de l’histoire."],
    corrige: P("La richesse de la Suisse ne vient pas de ressources naturelles, mais de facteurs que les théories de la croissance jugent décisifs. D’abord le <b>capital humain</b> : l’apprentissage dual forme une main-d’œuvre très qualifiée, et les écoles polytechniques (EPFZ, fondée en 1855, et EPFL) nourrissent la recherche.", "Ensuite l’<b>innovation et la spécialisation</b> dans des produits à forte valeur ajoutée : horlogerie, machines, chimie et pharmacie, souvent nées de l’industrie textile, puis services financiers. La Suisse figure en tête des classements mondiaux de l’innovation.", "Enfin des <b>institutions</b> stables et inclusives, au sens d’Acemoglu : État de droit, fédéralisme, démocratie directe, protection de la propriété, et une forte <b>ouverture</b> aux échanges et aux travailleurs étrangers. Le tunnel du Gothard et l’hydroélectricité ont compensé l’absence de charbon. Ces facteurs se renforcent mutuellement et expliquent une productivité élevée.", "D’autres facteurs sont plus discutés. Épargnée par les deux guerres mondiales, la Suisse a conservé son appareil de production et attiré des capitaux, ce qui a nourri sa place financière et maintenu des taux d’intérêt bas.") },

  { id: "cr2-convergence", theme: "croissance", niveau: 2, type: "qcm", notion: "modele-solow",
    titre: "Les pays pauvres rattrapent-ils les riches ?", competence: "Comprendre la convergence conditionnelle.",
    enonce: P("Le modèle de Solow prédit qu’un pays éloigné de son état stationnaire croît plus vite. Si tous les pays avaient le même taux d’épargne, la même démographie et les mêmes techniques, les pays pauvres devraient donc rattraper les riches. Que montrent les données depuis 1960 ?"),
    options: ["Un rattrapage général, la plupart des pays pauvres ayant crû plus vite que les pays riches.", "Un creusement général, l’écart s’étant accru entre les pays riches et presque tous les pays pauvres.", "Un rattrapage partiel, observé là où l’éducation, l’épargne et les institutions le permettent, comme en Corée du Sud.", "Un rattrapage limité aux pays qui disposent de pétrole ou de matières premières."], c: 2, pourquoi: ["Beaucoup de pays, en Afrique ou en Amérique latine, n’ont pas rattrapé leur retard depuis 1960.", "La Corée du Sud, Taïwan ou Singapour ont bien rattrapé les pays riches, et la Chine s’en rapproche.", null, "Les exemples les plus nets de rattrapage, comme la Corée du Sud ou Taïwan, sont pauvres en ressources naturelles."],
    explication: P("On observe une <b>convergence conditionnelle</b> : les pays rattrapent leur retard quand ils réunissent certaines conditions, comme l’éducation, l’épargne, l’ouverture et des institutions favorables. La Corée du Sud, Taïwan ou plus tard la Chine en sont des exemples. Beaucoup d’autres pays, en Afrique ou en Amérique latine, n’ont pas rattrapé leur retard.", "C’est l’une des raisons pour lesquelles les économistes se sont tournés vers les institutions (North, Acemoglu) pour expliquer les écarts de richesse.", "Depuis les années 2000, plusieurs études observent un rattrapage plus général des pays pauvres, sans que le débat soit clos.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "cr3-par-habitant", theme: "croissance", niveau: 3, type: "calcul", notion: "pib",
    titre: "Croissance totale et croissance par habitant", competence: "Calculer la croissance du PIB par habitant à partir de celles du PIB et de la population.",
    gen: () => { const n = pick([10, 15, 20]), gr = pick([1.2, 1.5, 1.8, 2.2]), pi = pick([0.8, 1.2, 1.6]), m = pick([0.6, 0.9, 1.1]); const Y0 = rnd(550, 700), P0 = rnd(70, 80) / 10; return { n, Y0, Y1: Math.round(Y0 * Math.pow((1 + gr / 100) * (1 + pi / 100), n)), D: Math.round(100 * Math.pow(1 + pi / 100, n)), P0, P1: Math.round(P0 * Math.pow(1 + m / 100, n) * 10) / 10 }; },
    enonce: (p) => P(`Sur une période de <b>${p.n} ans</b>, le PIB nominal d’un pays passe de <b>${p.Y0} à ${fmt(p.Y1)} milliards</b>. Le déflateur du PIB passe de 100 à <b>${p.D}</b>, et la population de <b>${fmt(p.P0, 1)} à ${fmt(p.P1, 1)} millions</b> d’habitants.`, "Calculez la croissance totale du PIB réel par habitant sur la période (arrondie à une décimale), puis son taux de croissance annuel moyen (arrondi à deux décimales)."),
    champs: [{ label: "Croissance totale du PIB réel par habitant", unite: "%", tol: 0.15 }, { label: "Taux annuel moyen", unite: "%", tol: 0.03 }],
    reponses: (p) => { const q = (p.Y1 / (p.D / 100) / p.Y0) / (p.P1 / p.P0); return [X.arr((q - 1) * 100, 1), X.arr((Math.pow(q, 1 / p.n) - 1) * 100, 2)]; },
    indice: "Passez d’abord du PIB nominal au PIB réel avec le déflateur, puis rapportez-le à la population. Cherchez enfin le taux qui, composé sur toute la période, redonne la croissance totale.",
    correction: (p) => { const r1 = p.Y1 / (p.D / 100), a0 = p.Y0 / p.P0, a1 = r1 / p.P1, q = a1 / a0, t = (Math.pow(q, 1 / p.n) - 1) * 100; return P(`PIB réel final = ${fmt(p.Y1)} ÷ ${fmt(p.D / 100, 2)} ≈ ${fmt(r1, 1)} milliards (aux prix de départ).`, `PIB réel par habitant : ${p.Y0} ÷ ${fmt(p.P0, 1)} ≈ ${fmt(a0, 1)} au départ et ${fmt(r1, 1)} ÷ ${fmt(p.P1, 1)} ≈ ${fmt(a1, 1)} à l’arrivée (en milliers de francs aux prix de départ, soit des milliards par million d’habitants). Rapport : ${fmt(q, 4)}, soit une croissance totale de <b>${fmt((q - 1) * 100, 1)} %</b>.`, `Taux annuel moyen : ${fmt(q, 4)}<sup>1/${p.n}</sup> − 1 ≈ <b>${fmt(t, 2)} %</b> par an.`, "La croissance du PIB nominal par habitant serait bien plus forte, car elle contient la hausse des prix. En Suisse, une part importante de la croissance du PIB depuis les années 2000 vient de l’augmentation de la population : la croissance par habitant, qui mesure mieux l’évolution du niveau de vie moyen, est nettement plus faible."); } },

  { id: "cr3-deflateur", theme: "croissance", niveau: 3, type: "calcul", notion: "pib",
    titre: "Le déflateur du PIB", competence: "Calculer un indice de prix à partir du PIB nominal et réel.",
    gen: () => { const R1 = rnd(700, 780), d1 = pick([102, 103, 104, 105, 106, 107]); let gr, inf; do { gr = pick([0.6, 1.5, 2.3, 3.2]); inf = pick([0.9, 1.4, 2, 2.8, 4]); } while (Math.abs(gr - inf) < 0.8); const R2 = Math.round(R1 * (1 + gr / 100)); const d2 = Math.round(d1 * (1 + inf / 100) * 10) / 10; return { d1, d2, N1: Math.round(R1 * d1 / 100), N2: Math.round(R2 * d2 / 100) }; },
    enonce: (p) => P("Les comptes d’un pays sont exprimés avec une année de base où le déflateur vaut 100. Le PIB nominal est de <b>" + p.N1 + " milliards</b> l’année 1 et de <b>" + p.N2 + " milliards</b> l’année 2. Le déflateur du PIB vaut <b>" + fmt(p.d1, 1) + "</b> l’année 1 et <b>" + fmt(p.d2, 1) + "</b> l’année 2.", "Calculez l’inflation indiquée par le déflateur entre les deux années, puis la croissance du PIB réel. Dites enfin à quoi tient surtout la variation du PIB nominal. Arrondissez à une décimale."),
    champs: [{ label: "Inflation (déflateur)", unite: "%", tol: 0.15 }, { label: "Croissance du PIB réel", unite: "%", tol: 0.15 }, { label: "La variation du PIB nominal tient surtout à", choix: ["la hausse des prix", "la variation de la production"] }],
    reponses: (p) => { const inf = (p.d2 / p.d1 - 1) * 100, cr = ((p.N2 / p.d2) / (p.N1 / p.d1) - 1) * 100; return [X.arr(inf, 1), X.arr(cr, 1), Math.abs(inf) > Math.abs(cr) ? 0 : 1]; },
    indice: "Le PIB réel est le PIB nominal divisé par le déflateur (en base 100). Comparez ensuite la croissance réelle et l’inflation.",
    correction: (p) => { const r1 = p.N1 / p.d1 * 100, r2 = p.N2 / p.d2 * 100, inf = (p.d2 / p.d1 - 1) * 100, cr = (r2 / r1 - 1) * 100; return P(`Inflation = ${fmt(p.d2, 1)} ÷ ${fmt(p.d1, 1)} − 1 ≈ <b>${fmt(inf, 1)} %</b>.`, `PIB réel (prix de l’année de base) : année 1 = ${p.N1} ÷ ${fmt(p.d1 / 100, 3)} ≈ ${fmt(r1, 1)} ; année 2 = ${p.N2} ÷ ${fmt(p.d2 / 100, 3)} ≈ ${fmt(r2, 1)}. Croissance réelle ≈ <b>${fmt(cr, 1)} %</b>.`, `Le PIB nominal a varié de ${fmt((p.N2 / p.N1 - 1) * 100, 1)} %. ${Math.abs(inf) > Math.abs(cr) ? "L’inflation est plus forte que la croissance réelle : cette variation tient surtout à la <b>hausse des prix</b>." : "La croissance réelle est plus forte que l’inflation : cette variation tient surtout à la <b>variation de la production</b>."}`, "Contrairement à l’IPC, qui mesure le prix d’un panier de consommation, le déflateur couvre toute la production du pays, y compris l’investissement et les exportations, mais pas les importations."); } },

  { id: "cr3-ppa", theme: "croissance", niveau: 3, type: "calcul", notion: "pib",
    titre: "Comparer les niveaux de vie en parité de pouvoir d’achat", competence: "Corriger un revenu des différences de prix entre pays.",
    gen: () => { const pA = pick([80, 100, 120]), r = pick([2, 2.5, 3, 4]), k = pick([0.8, 1.2, 1.5, 2]); const e = X.arr(r * k, 2); return { pA, r, e, pB: pA * r, ya: rnd(80, 100) * 1000, yB: Math.round(rnd(18, 40) * 1000 * e) }; },
    enonce: (p) => P(`Un même panier de biens et de services coûte <b>${p.pA} francs</b> dans le pays A, dont la monnaie est le franc, et <b>${fmt(p.pB)} unités</b> de monnaie locale (ML) dans le pays B. Le taux de change du marché est de <b>${fmt(p.e, 2)} ML</b> pour 1 franc.`, `Le revenu moyen par habitant est de <b>${fmt(p.ya)} francs</b> dans le pays A et de <b>${fmt(p.yB)} ML</b> dans le pays B.`, "Calculez le taux de change de parité de pouvoir d’achat (PPA), en ML pour 1 franc. Indiquez si le franc est surévalué ou sous-évalué par rapport à la PPA. Calculez enfin le revenu moyen du pays B en francs, d’abord au taux de change du marché, puis au taux de la PPA. Arrondissez le taux à deux décimales et les revenus au franc."),
    champs: [{ label: "Taux de change de la PPA", unite: "ML pour 1 fr.", tol: 0.011 }, { label: "Au taux du marché, le franc est", choix: ["surévalué par rapport à la PPA", "sous-évalué par rapport à la PPA"] }, { label: "Revenu de B au taux du marché", unite: "fr.", tol: 3 }, { label: "Revenu de B au taux de la PPA", unite: "fr.", tol: 3 }],
    reponses: (p) => [p.r, p.e > p.r ? 0 : 1, Math.round(p.yB / p.e), Math.round(p.yB / p.r)],
    indice: "La PPA est le taux de change qui rendrait le panier aussi cher dans les deux pays : comparez le prix du panier dans les deux pays.",
    correction: (p) => { const m = p.yB / p.e, q = p.yB / p.r; return P(`Taux de la PPA = ${fmt(p.pB)} ÷ ${p.pA} = <b>${fmt(p.r, 2)} ML</b> pour 1 franc.`, p.e > p.r ? `Le marché donne ${fmt(p.e, 2)} ML pour 1 franc, plus que les ${fmt(p.r, 2)} ML de la PPA : le franc est <b>surévalué</b> par rapport à la PPA, comme dans l’indice Big Mac.` : `Le marché ne donne que ${fmt(p.e, 2)} ML pour 1 franc, moins que les ${fmt(p.r, 2)} ML de la PPA : le franc est <b>sous-évalué</b> par rapport à la PPA.`, `Revenu de B au taux du marché : ${fmt(p.yB)} ÷ ${fmt(p.e, 2)} ≈ <b>${fmt(Math.round(m))} francs</b>. Au taux de la PPA : ${fmt(p.yB)} ÷ ${fmt(p.r, 2)} ≈ <b>${fmt(Math.round(q))} francs</b>.`, `Au taux du marché, A est ${fmt(p.ya / m, 2)} fois plus riche que B ; en PPA, ${fmt(p.ya / q, 2)} fois. ${p.e > p.r ? "Les prix plus bas du pays B font que son revenu pèse davantage en pouvoir d’achat qu’au taux de change." : "Ici, les prix du pays B sont proches ou supérieurs à ceux de A, et la PPA réduit son revenu apparent."} ${p.e > p.r ? "La Suisse, dont les prix sont parmi les plus élevés du monde, est dans le cas du pays A : l’écart avec ses voisins est plus faible en PPA." : "C’est l’inverse du cas de la Suisse, dont les prix élevés rendent l’écart avec ses voisins plus faible en PPA qu’au taux du marché."}`); } },

  { id: "cr3-coree", theme: "croissance", niveau: 3, type: "qcm", notion: "institutions-inclusives",
    titre: "Deux Corées, deux destins", competence: "Départager plusieurs explications des écarts de richesse entre pays.",
    enonce: P("Jusqu’en 1945, la Corée du Nord et la Corée du Sud partageaient la même histoire, la même langue et la même culture. Aujourd’hui, la Corée du Sud est un pays riche et la Corée du Nord l’un des plus pauvres du monde. Quelle explication privilégient Acemoglu et Robinson ?"),
    options: ["La géographie, car le Sud bénéficie d’un climat et de terres plus favorables à l’agriculture.", "Les ressources naturelles, car le Sud dispose de davantage de minerais et d’énergie.", "Les institutions, qui encouragent l’investissement au Sud (propriété privée, marchés) et servent une élite au Nord.", "La culture, car les valeurs de travail et d’épargne sont plus répandues au Sud."], c: 2, pourquoi: ["Les deux Corées ont presque le même climat et des terres comparables : la géographie ne peut pas expliquer un tel écart.", "C’est le Nord qui possède le plus de ressources minières : l’explication par les ressources ne tient pas.", null, "Les deux pays partageaient la même culture jusqu’en 1945 : c’est justement ce qui en fait une expérience naturelle."],
    explication: P("Pour Acemoglu et Robinson, c’est une sorte d’« expérience naturelle » : géographie, culture et histoire étaient semblables, seules les <b>institutions</b> ont divergé. Au Sud, des institutions de plus en plus <b>inclusives</b> ont encouragé l’investissement, l’éducation et l’innovation ; au Nord, des institutions <b>extractives</b> ont permis à une élite de capter les ressources, sans incitation à produire.", "Le Nord possède d’ailleurs davantage de ressources minières que le Sud, ce qui écarte l’explication par les ressources.", "Cette lecture est discutée. Le décollage sud-coréen, à partir des années 1960, s’est fait sous un régime autoritaire (la démocratie date de 1987) et avec une politique industrielle très dirigiste, ce que soulignent Alice Amsden ou Ha-Joon Chang. Pour d’autres auteurs, comme Edward Glaeser, ce sont la croissance et l’éducation qui ont ensuite rendu possibles de meilleures institutions.") },

  { id: "cr3-solow-calc", theme: "croissance", niveau: 3, type: "calcul", notion: "modele-solow",
    titre: "L’état stationnaire de Solow", competence: "Calculer le revenu de long terme dans un modèle simple.",
    gen: () => { const a = pick([[1 / 3, "1/3", "3/2", "1/2"], [0.4, "2/5", "5/3", "2/3"]]); return { al: a[0], alS: a[1], e1: a[2], e2: a[3], s: pick([0.2, 0.25, 0.3, 0.35]), n: pick([0.5, 1]), g: pick([1, 1.5, 2]), d: pick([4, 5]) }; },
    enonce: (p) => P(`Dans un modèle de Solow avec progrès technique, la production par unité de travail efficace est y = k<sup>${p.alS}</sup>, où k est le capital par unité de travail efficace. Le taux d’épargne est s = <b>${fmt(p.s, 2)}</b>. La population croît de <b>${fmt(p.n, 1)} %</b> par an, le progrès technique de <b>${fmt(p.g, 1)} %</b> par an, et le capital se déprécie de <b>${fmt(p.d, 1)} %</b> par an.`, "Écrivez la condition de l’état stationnaire, puis calculez k* et y*. Calculez aussi la demi-vie de la convergence, c’est-à-dire le temps nécessaire pour combler la moitié de l’écart avec l’état stationnaire, qui vaut ln 2 ÷ [(1 − α) × (n + g + δ)] avec α l’exposant du capital. Calculez enfin par combien est multiplié y* si le taux d’épargne double. Arrondissez à deux décimales (une décimale pour la demi-vie)."),
    champs: [{ label: "Capital k*", unite: "", tol: 0.1 }, { label: "Production y*", unite: "", tol: 0.02 }, { label: "Demi-vie de la convergence", unite: "ans", tol: 0.2 }, { label: "y* multiplié par, si s double", unite: "", tol: 0.011 }],
    reponses: (p) => { const q = (p.n + p.g + p.d) / 100, r = p.s / q; return [X.arr(Math.pow(r, 1 / (1 - p.al)), 2), X.arr(Math.pow(r, p.al / (1 - p.al)), 2), X.arr(Math.LN2 / ((1 - p.al) * q), 1), X.arr(Math.pow(2, p.al / (1 - p.al)), 2)]; },
    indice: "À l’état stationnaire, l’investissement s·k<sup>α</sup> compense l’usure et la dilution du capital (n + g + δ)·k. Isolez k, puis exprimez y avec k.",
    correction: (p) => { const q = (p.n + p.g + p.d) / 100, r = p.s / q, k = Math.pow(r, 1 / (1 - p.al)), y = Math.pow(k, p.al), h = Math.LN2 / ((1 - p.al) * q), f = Math.pow(2, p.al / (1 - p.al)); return P(`Condition : s × k<sup>${p.alS}</sup> = (n + g + δ) × k, avec n + g + δ = ${fmt(p.n, 1)} + ${fmt(p.g, 1)} + ${fmt(p.d, 1)} = ${fmt(q * 100, 1)} %. On en tire k<sup>1 − ${p.alS}</sup> = s ÷ (n + g + δ) = ${fmt(p.s, 2)} ÷ ${fmt(q, 3)} = ${fmt(r, 3)}.`, `Donc k* = ${fmt(r, 3)}<sup>${p.e1}</sup> ≈ <b>${fmt(k, 2)}</b>, et y* = k*<sup>${p.alS}</sup> = ${fmt(r, 3)}<sup>${p.e2}</sup> ≈ <b>${fmt(y, 2)}</b>.`, `Demi-vie = ln 2 ÷ [(1 − ${p.alS}) × ${fmt(q, 3)}] = ${fmt(Math.LN2, 3)} ÷ ${fmt((1 - p.al) * q, 4)} ≈ <b>${fmt(h, 1)} ans</b> : la convergence est lente.`, `Si s double, y* est multiplié par 2<sup>${p.e2}</sup> ≈ <b>${fmt(f, 2)}</b>, une hausse de ${fmt((f - 1) * 100, 0)} %, et non de 100 %, à cause des rendements décroissants du capital.`, "Un pays qui épargne davantage atteint un revenu par travailleur plus élevé, mais sa croissance par habitant s’arrête une fois l’état stationnaire atteint : à long terme, elle ne dépend que du progrès technique g."); } },

  { id: "cr3-vf-ralentissement", theme: "croissance", niveau: 3, type: "vf", notion: "stagnation-seculaire",
    titre: "Le ralentissement de la croissance", competence: "Connaître les débats sur la croissance future des pays riches.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Dans le modèle de Solow sans progrès technique, un pays qui double son taux d’épargne finit par connaître une croissance du revenu par habitant durablement plus forte.", false, "Le modèle prédit un effet de niveau, pas de croissance : le revenu par habitant de long terme est plus élevé, mais, à cause des rendements décroissants du capital, sa croissance retombe à zéro une fois le nouvel état stationnaire atteint."],
      ["En 1987, Robert Solow remarquait qu’on voyait les ordinateurs partout, sauf dans les statistiques de productivité.", true, "C’est le « paradoxe de la productivité ». Les gains liés à l’informatique sont finalement apparus aux États-Unis à la fin des années 1990, puis ont ralenti."],
      ["Dans un pays dont la population diminue de 1 % par an, un PIB réel qui stagne signifie aussi un PIB par habitant qui stagne.", false, "Le PIB par habitant est le rapport du PIB à la population : si le numérateur stagne et que le dénominateur baisse de 1 %, il augmente d’environ 1 % par an. Dans un pays qui vieillit, le PIB total peut donc stagner sans que le niveau de vie moyen recule."],
      ["Si le taux d’intérêt qui équilibre épargne et investissement est fortement négatif, comme le suppose la thèse de la stagnation séculaire, une baisse du taux directeur de la banque centrale peut ne pas suffire à ramener le plein emploi.", true, "Le taux directeur ne peut guère descendre sous zéro : il reste alors supérieur au taux d’équilibre, et la demande demeure insuffisante. C’est l’argument de Larry Summers (2013), repris d’Alvin Hansen (1938), qui plaide pour un soutien budgétaire ou une hausse de l’investissement."]
    ] },

  { id: "cr3-decroissance", theme: "croissance", niveau: 3, type: "redaction", notion: "pib",
    titre: "Croissance verte ou décroissance ?", competence: "Construire une argumentation sur les limites écologiques de la croissance.",
    enonce: P("Pour respecter l’Accord de Paris, la Suisse s’est engagée à atteindre zéro émission nette de gaz à effet de serre d’ici 2050. Certains pensent qu’on peut y parvenir en continuant à croître, grâce aux technologies propres ; d’autres jugent qu’il faudra réduire la production dans les pays riches.", "<b>Consigne :</b> la lutte contre le changement climatique est-elle compatible avec la poursuite de la croissance économique ? Présentez les deux positions, en utilisant au moins une notion d’économie. Rattachez chaque position à une école ou à un auteur, et dites sur quelle hypothèse ils s’opposent. Appuyez-vous sur au moins un fait ou un exemple, puis concluez par une prise de position explicite. Longueur attendue, 15 à 25 lignes."),
    criteres: ["La réponse nomme au moins deux écoles ou auteurs et l’hypothèse qui les sépare.", "La réponse présente la croissance verte (découplage entre production et émissions, innovation, énergies renouvelables, efficacité, taxe carbone…).", "Elle présente la décroissance ou post-croissance (limites physiques, effet rebond, découplage trop lent, critique du PIB comme objectif…).", "Elle nomme au moins une notion d’économie (PIB et ses limites, externalité, progrès technique, prix du carbone…) et l’explique en une phrase.", "Elle s’appuie sur au moins un exemple ou un fait : baisse des émissions en Suisse ou en Europe malgré la croissance, émissions importées, etc.", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Croissance verte :</b> pour ses partisans, la croissance peut se poursuivre si l’on <b>découple</b> la production des émissions, grâce aux énergies renouvelables, à l’efficacité énergétique et à l’innovation. Les émissions de gaz à effet de serre sont une <b>externalité</b> : en leur donnant un prix, par une taxe carbone comme le propose William Nordhaus, on oriente les choix vers des solutions propres. Plusieurs pays européens, dont la Suisse, ont réduit leurs émissions territoriales tout en continuant à croître.", "<b>Décroissance :</b> pour d’autres, ce découplage est trop lent et partiel : les émissions liées aux importations restent élevées, et les gains d’efficacité sont souvent annulés par une consommation accrue (effet rebond). Ils jugent qu’il faudra réduire la production matérielle dans les pays riches et remplacer le PIB par d’autres objectifs de bien-être.", "<b>L’hypothèse qui les sépare :</b> la possibilité de substituer du capital produit au capital naturel. William Nordhaus, dans la tradition néoclassique de Robert Solow, admet une « soutenabilité faible » : tant que les machines et les techniques remplacent les ressources épuisées, la croissance peut continuer. Nicholas Georgescu-Roegen, qui applique la loi de l’entropie à l’économie, et Herman Daly défendent une « soutenabilité forte » : le capital naturel n’est pas substituable, et l’économie est un sous-système d’une biosphère finie. Kate Raworth, avec son « donut », propose d’ailleurs de viser le bien-être à l’intérieur de limites écologiques plutôt que la croissance du PIB.", "<b>Conclusion :</b> la poursuite de la croissance n’est compatible avec le climat qu’à certaines conditions. La question n’est pas seulement de croître ou non, mais de savoir <b>quelle</b> croissance, et une transformation rapide de l’énergie et des transports, un prix du carbone et une mesure du progrès qui ne se limite pas au PIB semblent nécessaires dans les deux visions.") },

  { id: "cr3-idh", theme: "croissance", niveau: 3, type: "document", notion: "capabilites",
    titre: "Le revenu et le développement humain", competence: "Calculer les indices qui composent l’IDH à partir de données du PNUD et expliquer un écart entre revenu et développement humain.",
    enonce: P("Le tableau donne les composantes de l’indice de développement humain (IDH) de trois pays.") +
      `<table><thead><tr><th></th><th>Qatar</th><th>Chili</th><th>Sri Lanka</th></tr></thead><tbody><tr><td>Espérance de vie à la naissance (années)</td><td>82,4</td><td>81,2</td><td>77,5</td></tr><tr><td>Durée attendue de scolarisation (années)</td><td>13,1</td><td>16,9</td><td>13,1</td></tr><tr><td>Durée moyenne de scolarisation des adultes (années)</td><td>10,8</td><td>11,3</td><td>10,8</td></tr><tr><td>Revenu national brut par habitant ($ PPA de 2021)</td><td>105 353</td><td>28 047</td><td>12 616</td></tr><tr><td>IDH</td><td>0,886</td><td>0,878</td><td>0,776</td></tr><tr><td>Rang mondial selon l’IDH (sur 193)</td><td>43</td><td>45</td><td>89</td></tr></tbody></table><p class="ex-source">Source : PNUD, Rapport sur le développement humain 2025, données de 2023 (base des indices composites, mise à jour du 6 mai 2025).</p>` +
      P("Le PNUD calcule trois indices entre 0 et 1, puis en prend la moyenne géométrique. Indice de santé = (espérance de vie − 20) ÷ 65. Indice d’éducation = moyenne de (durée attendue ÷ 18) et de (durée moyenne ÷ 15). Indice de revenu = (ln RNB − ln 100) ÷ (ln 75 000 − ln 100), un revenu supérieur à 75 000 dollars étant ramené à 75 000.", "Calculez ces indices pour chaque pays, puis dites quelle conclusion est correcte."),
    options: ["Le Qatar, presque quatre fois plus riche que le Chili, a un IDH presque égal, car son indice de revenu plafonne à 1 et son éducation reste à 0,72.", "Le Qatar devance nettement les deux autres pays, car le revenu compte pour un tiers de l’indice et le sien est près de quatre fois plus élevé que celui du Chili.", "Le Sri Lanka a l’IDH le plus faible des trois surtout à cause de sa santé, puisque son espérance de vie est la plus basse du tableau.", "Le Chili rattrape le Qatar parce qu’une moyenne géométrique laisse un point d’éducation compenser exactement un point de revenu."], c: 0,
    pourquoi: [null, "Le revenu entre dans l’indice par son logarithme, et le PNUD le plafonne à 75 000 dollars. Le revenu du Qatar donne donc un indice de 1, contre 0,85 au Chili, et non quatre fois plus. L’écart d’IDH n’est que de 0,008.", "L’indice de santé du Sri Lanka vaut (77,5 − 20) ÷ 65 ≈ 0,88, à peine moins que celui du Chili (0,94). L’écart vient surtout du revenu (0,73 contre 0,85) et de l’éducation (0,72 contre 0,85).", "Une moyenne géométrique multiplie les indices. Un point gagné sur un indice ne compense pas exactement un point perdu sur un autre, et un indice faible pèse plus lourd qu’avec une moyenne simple."],
    explication: P("Indices de santé : Qatar (82,4 − 20) ÷ 65 ≈ 0,960, Chili ≈ 0,942, Sri Lanka ≈ 0,885.", "Indices d’éducation : Qatar (13,1 ÷ 18 + 10,8 ÷ 15) ÷ 2 ≈ 0,724, Chili (16,9 ÷ 18 + 11,3 ÷ 15) ÷ 2 ≈ 0,846, Sri Lanka ≈ 0,724.", "Indices de revenu : Qatar 1 (revenu plafonné), Chili (ln 28 047 − ln 100) ÷ (ln 75 000 − ln 100) ≈ 0,851, Sri Lanka ≈ 0,731.", "IDH : Qatar (0,960 × 0,724 × 1)<sup>1/3</sup> ≈ <b>0,886</b>, Chili (0,942 × 0,846 × 0,851)<sup>1/3</sup> ≈ <b>0,879</b>, Sri Lanka ≈ <b>0,776</b>. Le PNUD publie 0,878 pour le Chili, car il calcule sur les données non arrondies.", "Le Qatar tire un revenu très élevé de ses hydrocarbures, mais ce revenu se traduit peu en années d’études. Le Chili, quatre fois moins riche, obtient presque le même IDH grâce à l’éducation. À l’inverse, le Sri Lanka a la même éducation que le Qatar et une bonne santé pour un revenu modeste.", "L’IDH, conçu en 1990 par Mahbub ul Haq avec Amartya Sen, traduit l’idée que le revenu est un moyen et que ce qui compte, ce sont les <b>capabilités</b>, ce que les personnes peuvent réellement être et faire. Ses choix restent discutés. Le logarithme et le plafond réduisent fortement le poids du revenu, la moyenne pondère les trois dimensions à égalité, et l’indice ignore la répartition entre les habitants. Martin Ravallion a montré que ces choix fixent implicitement la valeur d’une année d’espérance de vie en dollars, très différente d’un pays à l’autre.") },
  { id: "cr1-fait-valeur", theme: "croissance", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Un jugement se cache-t-il dans la phrase ?", competence: "Repérer un jugement de valeur caché dans une phrase d’apparence factuelle et reconnaître un constat ou une prévision vérifiable.",
    enonce: P("Ces phrases ont toutes l’air de décrire la réalité. Pour chacune, dites s’il s’agit d’un <b>constat</b>, que l’on peut vérifier avec des données, même s’il se révèle faux, ou d’un <b>jugement de valeur</b> déguisé, qui repose sur un critère de ce qui est bien ou important. Une prévision, que les chiffres confirmeront ou non, se classe parmi les constats."),
    affirmations: [
      ["Un taux de croissance de 1 % par an est trop faible pour un pays riche.", false, "Aucun mot comme « devrait » ne l’annonce, mais « trop faible » suppose un critère de ce qu’il faut atteindre. Les données donnent le taux, pas le seuil à partir duquel il est satisfaisant."],
      ["Le revenu moyen par habitant dans le monde a été multiplié par plus de dix depuis 1820.", true, "On peut le vérifier avec des données, comme les estimations d’Angus Maddison. Que cette hausse soit une bonne chose est une autre question."],
      ["Si la population d’un pays augmente de 2 % et son PIB réel de 1 % en un an, son PIB réel par habitant diminuera.", true, "C’est une prévision, qui se vérifie par un calcul : 1,01 ÷ 1,02 − 1 est négatif. Elle ne dit pas si c’est souhaitable."],
      ["Le PIB laisse de côté l’essentiel de ce qui fait la qualité d’une vie.", false, "Le mot « essentiel » cache un jugement sur ce qui compte le plus. On peut mesurer ce que le PIB ne compte pas, mais pas trancher ce qui est essentiel."],
      ["Une croissance tirée par la hausse de la population est moins satisfaisante qu’une croissance tirée par la productivité.", false, "On peut mesurer la part de chaque source, mais « moins satisfaisante » dépend du critère retenu : niveau de vie moyen, taille de l’économie, effet sur l’environnement."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "cr1-graph-recession", theme: "croissance", niveau: 1, type: "graphique", notion: "cycles",
    titre: "Ralentissement ou récession ?", competence: "Lire un graphique de taux de croissance et distinguer un ralentissement d’un recul de la production.",
    enonce: P("Le graphique donne la croissance annuelle du PIB réel d’un pays.", "Que montre-t-il pour 2021 et pour 2022 ?"),
    fig: () => X.barres({ cats: ["2019", "2020", "2021", "2022", "2023", "2024"], vals: [2, 3, 1, -2, 1, 2], ymin: -3.2, ymax: 4, unite: " %", dec: 0, col: "d", aria: "Croissance du PIB réel de 2019 à 2024 : 2, 3, 1, moins 2, 1 puis 2 pour cent", caption: "Croissance annuelle du PIB réel. Données inventées pour l’exercice." }),
    options: ["En 2021 la production augmente moins vite, en 2022 elle diminue.", "La production diminue dès 2021, puisque la barre est plus basse qu’en 2020.", "La production diminue en 2022, puis retrouve dès 2023 son niveau de 2021.", "La production est la plus élevée en 2020, l’année où la barre est la plus haute."], c: 0,
    pourquoi: [null, "En 2021, la croissance est de 1 %. La production augmente encore, mais moins vite qu’en 2020. Elle ne diminue que si le taux devient négatif.", "Après une baisse de 2 %, une hausse de 1 % ne suffit pas. La production de 2023 reste environ 1 % sous celle de 2021.", "La hauteur d’une barre mesure la vitesse de la hausse, pas le niveau atteint. La production de 2021 dépasse celle de 2020, puisqu’elle a encore augmenté de 1 %."],
    explication: P("Chaque barre donne la <b>variation</b> de la production par rapport à l’année précédente. Une barre plus courte mais positive signale un <b>ralentissement</b>. Une barre négative signale un <b>recul</b> de la production, c’est-à-dire une récession.", "En 2021, la production augmente de 1 %. En 2022, elle diminue de 2 %. Il faut ensuite plus d’une année de croissance pour retrouver le niveau perdu.") },

  { id: "cr1-productivite", theme: "croissance", niveau: 1, type: "calcul",
    titre: "La productivité du travail", competence: "Calculer une productivité horaire à partir d’une valeur ajoutée et d’un nombre d’heures.",
    gen: () => { const n = rnd(20, 60), prod = rnd(50, 95), h = n * 1800; return { n, h, prod, va: h * prod }; },
    enonce: (p) => P(`Une entreprise de ${p.n} personnes crée en une année une valeur ajoutée de <b>${fmt(p.va)} francs</b>. Ses salariés ont travaillé <b>${fmt(p.h)} heures</b> au total.`, "Quelle est la productivité du travail, en francs de valeur ajoutée par heure travaillée ?"),
    champs: [{ label: "Productivité horaire", unite: "fr. par heure", tol: 0.01 }],
    reponses: (p) => [p.prod],
    indice: "La productivité du travail rapporte ce qui est produit à la quantité de travail utilisée.",
    correction: (p) => P(`Productivité horaire = valeur ajoutée ÷ heures travaillées = ${fmt(p.va)} ÷ ${fmt(p.h)}`, `= <b>${p.prod} francs</b> par heure.`, "À long terme, les salaires et le niveau de vie d’un pays suivent la productivité. Produire davantage par heure, grâce aux machines, à la formation ou à une meilleure organisation, est la source principale de la croissance du revenu par habitant.") },

  { id: "cr1-doc-va", theme: "croissance", niveau: 1, type: "document", notion: "pib",
    titre: "La valeur ajoutée d’une boulangerie", competence: "Retrouver la valeur ajoutée d’une entreprise dans ses comptes.",
    enonce: P("Voici les comptes simplifiés d’une boulangerie pour une année.") +
      `<table><thead><tr><th>Poste</th><th>Montant (fr.)</th></tr></thead><tbody><tr><td>Ventes</td><td>600 000</td></tr><tr><td>Achats de farine et d’ingrédients</td><td>150 000</td></tr><tr><td>Énergie, loyer et assurances</td><td>90 000</td></tr><tr><td>Salaires et cotisations sociales</td><td>250 000</td></tr><tr><td>Amortissement du four</td><td>30 000</td></tr><tr><td>Bénéfice</td><td>80 000</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle est la valeur ajoutée de cette boulangerie, c’est-à-dire sa contribution au PIB ?"),
    options: ["360 000 francs, les ventes moins les biens et les services achetés à d’autres entreprises.", "600 000 francs, le total des ventes de l’année.", "80 000 francs, le bénéfice qui reste une fois toutes les charges payées.", "110 000 francs, les ventes moins les achats, les autres charges et les salaires."], c: 0,
    pourquoi: [null, "Les ventes contiennent la valeur de la farine, de l’énergie ou du loyer, déjà produite par d’autres entreprises. Les compter ici reviendrait à les compter deux fois dans le PIB.", "Le bénéfice n’est qu’une partie de la valeur ajoutée. Les salaires et l’usure du four en font aussi partie, car ils rémunèrent le travail et le capital de la boulangerie.", "Les salaires ne sont pas un achat à une autre entreprise. Ils sont un revenu créé dans la boulangerie et font donc partie de sa valeur ajoutée."],
    explication: P("Valeur ajoutée = ventes − consommations intermédiaires = 600 000 − 150 000 − 90 000 = <b>360 000 francs</b>.", "Cette valeur se répartit entre les salariés (250 000 francs), le remplacement du capital usé (30 000 francs) et le bénéfice (80 000 francs). La somme fait bien 360 000 francs.", "Le PIB d’un pays est la somme des valeurs ajoutées de tous ses producteurs. Additionner les ventes compterait plusieurs fois la même farine.") },

  /* ----- Niveau 2 ----- */
  { id: "cr2-graph-solow", theme: "croissance", niveau: 2, type: "graphique", notion: "modele-solow",
    titre: "Le diagramme de Solow", competence: "Lire le diagramme de Solow et prévoir l’effet d’une hausse du taux d’épargne.",
    enonce: P("Le graphique représente le modèle de Solow. La courbe s·f(k) donne l’investissement par travailleur, la droite (n + δ)·k l’investissement nécessaire pour maintenir le capital par travailleur k. Le taux d’épargne passe de s à s′.", "Que prédit le modèle ?"),
    fig: () => X.graphe({ xmax: 104, ymax: 5.6, ylab: "Investissement par travailleur", xlab: "Capital par travailleur k", aria: "Diagramme de Solow : deux courbes d’investissement et la droite de l’investissement nécessaire",
      gx: [[36, "36"], [64, "64"]], reperes: [[36, 1.8], [64, 3.2]],
      lignes: [{ pts: [[0, 0], [100, 5]], col: "n", lab: "(n + δ)·k", at: [100, 5], dx: -4, dy: -10, anc: "end" }, { f: (k) => 0.3 * Math.sqrt(k), de: 0, a: 100, col: "d", lab: "s·f(k)", at: [100, 3], dy: 20, anc: "end" }, { f: (k) => 0.4 * Math.sqrt(k), de: 0, a: 100, col: "o", dash: true, lab: "s′·f(k)", at: [100, 4], dy: 20, anc: "end" }],
      points: [{ x: 36, y: 1.8, lab: "A", dx: -6, dy: -12, anc: "end" }, { x: 64, y: 3.2, lab: "B", col: "o", dx: -6, dy: -12, anc: "end" }],
      caption: "Avec f(k) = √k, s = 0,3, s′ = 0,4 et n + δ = 0,05." }),
    options: ["Le capital par travailleur augmente de 36 à 64, puis le revenu par travailleur cesse de nouveau de croître.", "Le capital par travailleur continue d’augmenter, car chaque franc épargné finance un investissement de plus.", "Le revenu par travailleur croît désormais plus vite de façon permanente, au rythme du nouveau taux d’épargne.", "Rien ne change à long terme, car la dépréciation absorbe tout l’investissement supplémentaire."], c: 0,
    pourquoi: [null, "La courbe d’investissement s’aplatit, car le capital a des rendements décroissants. Au point B, tout l’investissement sert à maintenir le capital existant, et k cesse d’augmenter.", "La croissance n’est plus forte que pendant la transition de A à B. Une fois en B, le revenu par travailleur ne croît plus, sauf progrès technique. L’épargne change le niveau du revenu, pas son taux de croissance de long terme.", "Le nouvel état stationnaire est en B, avec un capital par travailleur de 64 au lieu de 36. Le revenu par travailleur y est plus élevé."],
    explication: P("L’état stationnaire se trouve là où l’investissement est égal à l’investissement nécessaire. Avec s = 0,3, c’est le point A, où 0,3 × √36 = 1,8 = 0,05 × 36.", "Quand le taux d’épargne monte à 0,4, l’investissement dépasse en A ce qu’il faut pour maintenir k. Le capital par travailleur augmente jusqu’en B, où 0,4 × √64 = 3,2 = 0,05 × 64.", "Le revenu par travailleur passe de √36 = 6 à √64 = 8. C’est un <b>effet de niveau</b>. À long terme, seul le progrès technique fait croître durablement le revenu par travailleur, et le modèle de Solow ne l’explique pas. C’est ce que les théories de la croissance endogène ont cherché à corriger.") },

  { id: "cr2-tcam", theme: "croissance", niveau: 2, type: "calcul", notion: "pib",
    titre: "Le taux de croissance annuel moyen", competence: "Calculer une croissance totale et un taux de croissance annuel moyen.",
    gen: () => { const a = rnd(8, 30) * 1000, g = pick([1.5, 2, 3, 4, 5, 7]), n = pick([10, 20, 25]); return { a, n, b: Math.round(a * Math.pow(1 + g / 100, n) / 100) * 100 }; },
    enonce: (p) => P(`Le PIB réel par habitant d’un pays passe de <b>${fmt(p.a)} dollars</b> à <b>${fmt(p.b)} dollars</b> en <b>${p.n} ans</b>.`, "Calculez sa croissance totale sur la période (arrondie à une décimale), puis son taux de croissance annuel moyen (arrondi à deux décimales)."),
    champs: [{ label: "Croissance totale", unite: "%", tol: 0.1 }, { label: "Taux annuel moyen", unite: "%", tol: 0.02 }],
    reponses: (p) => [Math.round((p.b / p.a - 1) * 1000) / 10, Math.round((Math.pow(p.b / p.a, 1 / p.n) - 1) * 10000) / 100],
    indice: "Le taux annuel moyen n’est pas la croissance totale divisée par le nombre d’années. Cherchez le taux qui, appliqué chaque année, fait passer de la valeur de départ à la valeur d’arrivée.",
    correction: (p) => { const q = p.b / p.a, t = (Math.pow(q, 1 / p.n) - 1) * 100; return P(`Le PIB par habitant est multiplié par ${fmt(p.b)} ÷ ${fmt(p.a)} ≈ ${fmt(q, 4)}.`, `Croissance totale = (${fmt(q, 4)} − 1) × 100 ≈ <b>${fmt((q - 1) * 100, 1)} %</b>.`, `Taux annuel moyen = ${fmt(q, 4)}<sup>1/${p.n}</sup> − 1 ≈ <b>${fmt(t, 2)} %</b> par an.`, `Diviser la croissance totale par ${p.n} donnerait ${fmt((q - 1) * 100 / p.n, 2)} % par an, ce qui est trop. Cette méthode oublie que chaque année de croissance s’applique à un revenu déjà plus élevé.`); } },

  { id: "cr2-doc-depenses", theme: "croissance", niveau: 2, type: "document", notion: "pib",
    titre: "Le PIB par les dépenses", competence: "Reconstituer le PIB à partir de ses composantes et lire sa variation.",
    enonce: P("Le tableau donne les dépenses d’un pays pendant deux années, en milliards et à prix constants.") +
      `<table><thead><tr><th>Dépense</th><th>Année 1</th><th>Année 2</th></tr></thead><tbody><tr><td>Consommation des ménages</td><td>400</td><td>408</td></tr><tr><td>Dépenses publiques</td><td>100</td><td>101</td></tr><tr><td>Investissement</td><td>150</td><td>141</td></tr><tr><td>Exportations</td><td>300</td><td>318</td></tr><tr><td>Importations</td><td>250</td><td>258</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle lecture est correcte ?"),
    options: ["Le PIB augmente de 10 milliards, soit environ 1,4 %, alors que l’investissement recule de 9 milliards.", "Le PIB augmente de 26 milliards, car la hausse des importations s’ajoute à celle des autres dépenses.", "Le PIB recule, puisque l’investissement diminue et que les importations augmentent.", "Le PIB augmente de 10 milliards, et cette hausse vient entièrement de la consommation des ménages."], c: 0,
    pourquoi: [null, "Les importations se soustraient. Elles sont produites à l’étranger, alors que le PIB mesure la production du pays. Avec ce signe, la variation est de 8 + 1 − 9 + 18 − 8 = 10 milliards.", "Les deux mouvements pèsent sur le PIB, mais ils sont plus que compensés par la consommation (+8), les dépenses publiques (+1) et les exportations (+18).", "La consommation n’apporte que 8 milliards. Le solde extérieur, exportations moins importations, passe de 50 à 60 milliards et apporte 10 milliards à lui seul."],
    explication: P("PIB = consommation + dépenses publiques + investissement + exportations − importations.", "Année 1 : 400 + 100 + 150 + 300 − 250 = <b>700</b>. Année 2 : 408 + 101 + 141 + 318 − 258 = <b>710</b>. La croissance est de 10 ÷ 700 ≈ <b>1,4 %</b>.", "Chaque composante a une contribution, égale à sa variation divisée par le PIB de départ. La consommation apporte 1,1 point, les dépenses publiques 0,1 point, le solde extérieur 1,4 point, et l’investissement retire 1,3 point. La croissance vient donc de l’étranger et des ménages, pendant que les entreprises investissent moins.") },

  { id: "cr2-vf-cycles", theme: "croissance", niveau: 2, type: "vf", notion: "cycles",
    titre: "Récessions et reprises", competence: "Appliquer les notions d’écart de production et de stabilisateurs, et distinguer les lectures des cycles réels et de Keynes.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Un écart de production négatif signifie que l’économie produit davantage que son potentiel.", false, "C’est l’inverse. La production est alors inférieure à ce que l’économie pourrait produire avec ses travailleurs et ses équipements, et le chômage est plus élevé que d’ordinaire."],
      ["Pendant une récession, les recettes fiscales baissent et les indemnités de chômage augmentent sans décision nouvelle, ce qui soutient la demande.", true, "Ce sont les stabilisateurs automatiques. Le budget amortit le choc de lui-même, d’autant plus que les impôts et les assurances sociales pèsent lourd dans l’économie."],
      ["Pour la théorie des cycles réels, les récessions viennent surtout de chocs de productivité, et non d’un manque de demande.", true, "C’est la thèse de Finn Kydland et d’Edward Prescott. Les fluctuations y sont la réponse efficace de l’économie à des chocs techniques, ce qui laisse peu de place à une politique de relance."],
      ["Pour Keynes, une baisse générale des salaires ramène rapidement le plein emploi pendant une récession.", false, "Keynes soutient le contraire. Une baisse générale des salaires réduit les revenus et la demande, ce qui peut aggraver la récession au lieu de la corriger."]
    ] },

  /* ----- Niveau 3 ----- */
  { id: "cr3-cobb-douglas", theme: "croissance", niveau: 3, type: "calcul", notion: "modele-solow",
    titre: "Fonction de production et répartition", competence: "Calculer des productivités marginales et en déduire le partage du revenu.",
    gen: () => { const A = pick([2, 3, 5]); if (pick([0, 1])) { const rk = pick([10, 20, 30, 40]), rl = pick([5, 10, 15, 20]); return { A, al: 0.5, K: rk * rk, L: rl * rl, Y: A * rk * rl }; } const k4 = pick([2, 3, 4, 5]), l4 = pick([2, 3, 4]); return { A, al: 0.25, K: k4 ** 4, L: l4 ** 4, Y: A * k4 * l4 ** 3 }; },
    enonce: (p) => P(`La production d’une économie est donnée par <b>Y = ${p.A} × K<sup>${fmt(p.al)}</sup> × L<sup>${fmt(1 - p.al)}</sup></b>, avec un capital K = <b>${fmt(p.K)}</b> et un travail L = <b>${fmt(p.L)}</b>.`, "Calculez la production, puis la productivité marginale du travail et celle du capital, c’est-à-dire les dérivées partielles de Y. Arrondissez à trois décimales."),
    champs: [{ label: "Production Y", unite: "", tol: 0.05 }, { label: "Productivité marginale du travail", unite: "", tol: 0.002 }, { label: "Productivité marginale du capital", unite: "", tol: 0.002 }],
    reponses: (p) => [p.Y, Math.round((1 - p.al) * p.Y / p.L * 1000) / 1000, Math.round(p.al * p.Y / p.K * 1000) / 1000],
    indice: "Dérivez Y par rapport à L en tenant K constant. puis exprimez le résultat avec Y et L pour le simplifier. Procédez de même pour le capital.",
    correction: (p) => { const pl = (1 - p.al) * p.Y / p.L, pk = p.al * p.Y / p.K; return P(`Production : Y = ${p.A} × ${fmt(p.K)}<sup>${fmt(p.al)}</sup> × ${fmt(p.L)}<sup>${fmt(1 - p.al)}</sup> = <b>${fmt(p.Y)}</b>.`, `Productivité marginale du travail : ∂Y/∂L = ${fmt(1 - p.al)} × Y ÷ L = ${fmt(1 - p.al)} × ${fmt(p.Y)} ÷ ${fmt(p.L)} = <b>${fmt(pl, 3)}</b>.`, `Productivité marginale du capital : ∂Y/∂K = ${fmt(p.al)} × Y ÷ K = ${fmt(p.al)} × ${fmt(p.Y)} ÷ ${fmt(p.K)} = <b>${fmt(pk, 3)}</b>.`, `Si chaque facteur est payé à sa productivité marginale, le travail reçoit ${fmt(pl, 3)} × ${fmt(p.L)} = ${fmt(pl * p.L)}, soit ${fmt((1 - p.al) * 100)} % du revenu, et le capital ${fmt(p.al * 100)} %. Les deux parts épuisent exactement la production, parce que les rendements d’échelle sont constants.`, "Cette fonction prédit des parts stables du travail et du capital, égales aux exposants. C’est la lecture néoclassique de la répartition. Joan Robinson et les économistes de Cambridge l’ont contestée, en soutenant qu’on ne peut pas mesurer « le capital » sans connaître déjà sa rémunération, et que le partage du revenu dépend aussi du rapport de force entre salariés et employeurs."); } },

  { id: "cr3-regle-or", theme: "croissance", niveau: 3, type: "calcul", notion: "modele-solow",
    titre: "La règle d’or de l’accumulation", competence: "Trouver le taux d’épargne qui maximise la consommation à l’état stationnaire.",
    gen: () => ({ s: pick([0.1, 0.2, 0.3, 0.6, 0.7, 0.8]), nd: pick([0.05, 0.1]) }),
    enonce: (p) => P(`Dans un modèle de Solow sans progrès technique, la production par travailleur est <b>y = √k</b>. Le taux d’épargne est <b>s = ${fmt(p.s)}</b>, et la somme du taux de croissance de la population et du taux de dépréciation vaut <b>n + δ = ${fmt(p.nd)}</b>.`, "Calculez la consommation par travailleur à l’état stationnaire. Trouvez ensuite le taux d’épargne qui rendrait cette consommation maximale (règle d’or), et la consommation correspondante. Arrondissez à deux décimales."),
    champs: [{ label: "Consommation à l’état stationnaire", unite: "", tol: 0.01 }, { label: "Taux d’épargne de la règle d’or", unite: "%", tol: 0.5 }, { label: "Consommation à la règle d’or", unite: "", tol: 0.01 }],
    reponses: (p) => [Math.round((1 - p.s) * p.s / p.nd * 100) / 100, 50, 0.25 / p.nd],
    indice: "À l’état stationnaire, s√k = (n + δ)k, donc √k = s ÷ (n + δ). Écrivez la consommation c = (1 − s)·y en fonction de s seulement, puis cherchez son maximum.",
    correction: (p) => { const y = p.s / p.nd; return P(`État stationnaire : s√k = (n + δ)k, donc y* = √k* = s ÷ (n + δ) = ${fmt(p.s)} ÷ ${fmt(p.nd)} = ${fmt(y)}.`, `Consommation : c* = (1 − s) × y* = ${fmt(1 - p.s)} × ${fmt(y)} = <b>${fmt((1 - p.s) * y, 2)}</b>.`, `En fonction de s, c* = (1 − s) × s ÷ (n + δ). La dérivée (1 − 2s) ÷ (n + δ) s’annule pour s = <b>50 %</b>. C’est l’exposant du capital dans y = k<sup>0,5</sup>.`, `Consommation à la règle d’or : 0,5 × 0,5 ÷ ${fmt(p.nd)} = <b>${fmt(0.25 / p.nd, 2)}</b>.`, p.s > 0.5 ? "Ici le pays épargne plus que la règle d’or. Il accumule tant de capital que son entretien absorbe trop de production. En épargnant moins, il pourrait consommer davantage aujourd’hui et à toutes les dates futures. C’est une inefficience dynamique." : "Ici le pays épargne moins que la règle d’or. Épargner davantage augmenterait la consommation de long terme, mais au prix d’une consommation plus faible pendant la transition. Le choix dépend du poids donné aux générations futures.", "La règle d’or, due à Edmund Phelps (1961), dit quel état stationnaire est le meilleur. Elle ne dit pas qu’une économie de marché y parvient d’elle-même."); } },

  { id: "cr3-graph-convergence", theme: "croissance", niveau: 3, type: "graphique", notion: "modele-solow",
    titre: "Convergence et biais de sélection", competence: "Interpréter un nuage de points et repérer un biais de sélection.",
    enonce: P("Chaque point du graphique représente un pays. En abscisse figure son revenu par habitant en 1960, en ordonnée sa croissance annuelle moyenne de 1960 à 2020. Les points verts sont des pays aujourd’hui riches, les points dorés les autres pays.", "Que peut-on conclure sur la convergence ?"),
    fig: () => X.graphe({ xmax: 21, ymax: 6.6, ylab: "Croissance annuelle (%)", xlab: "Revenu en 1960 (milliers de $)", aria: "Nuage de points : relation décroissante pour les pays aujourd’hui riches, aucune relation pour les autres",
      gx: [[5, "5"], [10, "10"], [15, "15"], [20, "20"]], gy: [[2, "2"], [4, "4"], [6, "6"]],
      points: [[3, 4.6], [4.5, 4.1], [6, 3.6], [8, 3.1], [10, 2.8], [12, 2.5], [14, 2.3], [16, 2.1], [18, 1.9]].map(([x, y]) => ({ x, y, col: "d" })).concat([[1, 0.4], [1.2, 2.2], [1.5, 3.6], [1.8, 0.9], [2, 1.6], [2.4, 3.0], [2.6, 0.2], [3, 2.6], [3.5, 1.1], [4, 0.6], [4.6, 2], [5.5, 1.3], [6.5, 0.5], [7.5, 1.6]].map(([x, y]) => ({ x, y, col: "o" }))),
      caption: "Schéma construit pour l’exercice, d’après le débat entre William Baumol et Bradford De Long sur la convergence." }),
    options: ["Parmi les pays aujourd’hui riches, les plus pauvres en 1960 ont crû le plus vite, mais pas dans l’ensemble des pays.", "Les pays pauvres rattrapent les pays riches, comme le prédit le modèle de Solow pour des pays aux mêmes paramètres.", "Aucune convergence n’apparaît, ni pour l’ensemble des pays ni parmi les pays aujourd’hui riches.", "Les pays les plus riches en 1960 ont crû le plus vite, ce qui a creusé les écarts dans les deux groupes."], c: 0,
    pourquoi: [null, "Les points dorés ne dessinent aucune relation. Plusieurs pays très pauvres en 1960 ont une croissance inférieure à 1 % par an et n’ont pas rattrapé les autres.", "Les points verts forment une relation décroissante nette. Dans ce groupe, un revenu de départ plus faible va avec une croissance plus forte.", "Parmi les points verts, les pays les plus riches en 1960 sont ceux qui ont crû le plus lentement, autour de 2 % par an."],
    explication: P("Les points verts montrent une convergence. Mais ces pays ont été choisis parce qu’ils sont riches <b>aujourd’hui</b>. Un pays pauvre en 1960 ne peut figurer dans ce groupe que s’il a crû vite. Bradford De Long a montré en 1988 que la convergence trouvée par William Baumol venait en bonne partie de ce <b>biais de sélection</b>.", "Sur l’ensemble des pays, il n’y a pas de convergence absolue. Le modèle de Solow ne la prédit d’ailleurs que pour des pays qui ont le même taux d’épargne, la même démographie et les mêmes techniques. On parle de <b>convergence conditionnelle</b>, que les travaux de Robert Barro et de Gregory Mankiw, David Romer et David Weil ont cherché à mesurer.", "Les explications divergent ensuite. Pour les uns, les pays qui stagnent manquent de capital physique et humain. Pour Daron Acemoglu et James Robinson, ce sont leurs institutions qui découragent l’investissement. Pour les théories de la croissance endogène, les idées et le savoir-faire se concentrent là où ils sont déjà abondants.") },

  { id: "cr3-red-sources", theme: "croissance", niveau: 3, type: "redaction", notion: "destruction-creatrice",
    titre: "D’où vient la croissance à long terme ?", competence: "Comparer plusieurs théories de la croissance et leurs conséquences pour la politique économique.",
    enonce: P("Depuis deux siècles, le revenu par habitant des pays industrialisés a été multiplié par plus de quinze, alors que d’autres pays sont restés pauvres. Les économistes n’expliquent pas tous cet écart de la même façon.", "<b>Consigne :</b> comparez au moins trois explications de la croissance à long terme en nommant leurs auteurs (Solow ; Romer ou Lucas ; Schumpeter ou Aghion et Howitt ; North ou Acemoglu et Robinson). Pour chacune, indiquez le moteur de la croissance, ce qu’elle prédit sur le rattrapage des pays pauvres et la politique qu’elle inspire. Illustrez par au moins un exemple de pays, puis prenez position. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse présente au moins trois explications et nomme leurs auteurs.", "Elle indique pour chacune le moteur de la croissance (accumulation du capital et progrès technique donné, savoir et capital humain, innovation et destruction créatrice, institutions).", "Elle dit ce que chaque explication prédit sur le rattrapage des pays pauvres.", "Elle associe à chaque explication une politique (épargne et investissement, éducation et recherche, concurrence et entrée de nouvelles entreprises, État de droit).", "Elle s’appuie sur au moins un exemple de pays et se termine par une prise de position explicite, justifiée par un des arguments présentés."],
    corrige: P("<b>Solow.</b> La croissance du revenu par habitant vient de l’accumulation du capital, dont les rendements sont décroissants, et à long terme d’un progrès technique que le modèle ne cherche pas à expliquer. Un pays éloigné de son état stationnaire croît plus vite. Le modèle prédit donc un rattrapage entre pays comparables et recommande d’épargner et d’investir, sans promettre une croissance durablement plus forte.", "<b>Croissance endogène.</b> Pour Paul Romer et Robert Lucas, le savoir et le capital humain ne s’usent pas quand on les partage et profitent à toute l’économie. Les rendements ne décroissent plus, et un pays peut croître durablement plus vite qu’un autre. Rien ne garantit le rattrapage. La politique passe par l’éducation et le soutien à la recherche, puisque le marché seul en produit trop peu.", "<b>Schumpeter, Aghion et Howitt.</b> Le moteur est l’innovation, portée par des entreprises qui cherchent une rente temporaire et remplacent les anciennes. Loin de la frontière technologique, un pays peut croître en imitant. Près de la frontière, il lui faut de la concurrence, des universités et un financement du risque. Les politiques qui protègent les entreprises installées freinent la croissance.", "<b>Institutions.</b> Pour Douglass North, puis Daron Acemoglu et James Robinson, l’épargne, l’éducation et l’innovation sont des conséquences. La cause première est la qualité des institutions, qui protègent ou non la propriété et ouvrent ou non l’activité économique au plus grand nombre. Le rattrapage n’a donc lieu que si les institutions changent, et l’aide ou le transfert de techniques n’y suffisent pas. La politique consiste à renforcer l’État de droit et la protection de la propriété, ce qui est lent et dépend de rapports de force politiques. L’écart entre les deux Corées, de même culture et de même géographie, en est l’exemple le plus cité.", "<b>Prise de position possible.</b> Ces explications se complètent plus qu’elles ne s’excluent. Le décollage de la Corée du Sud s’est fait par une accumulation rapide de capital et par l’éducation, sous un régime autoritaire et avec une politique industrielle dirigiste, ce qui nuance la thèse des institutions. Mais une croissance fondée sur l’imitation s’essouffle à l’approche de la frontière technologique, et l’innovation suppose alors des institutions plus ouvertes. L’explication par les institutions paraît la plus générale, à condition d’admettre qu’elles évoluent avec le développement.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
